package com.bank.loans.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.loans.adapters.in.rest.SimulateConsumerLoanRequest;
import com.bank.loans.adapters.in.rest.SimulateConsumerLoanResponse;
import com.bank.loans.domain.error.BusinessError;
import com.bank.loans.domain.port.SimulationRepository;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class SimulateConsumerLoanServiceTest {

    private static final String AMOUNT_MESSAGE = "El monto debe estar entre 1.000 y 50.000";
    private static final String TERM_MESSAGE = "El plazo debe estar entre 6 y 60 meses";

    private record SavedCall(
            BigDecimal monto,
            Integer plazo,
            BigDecimal tasaAnual,
            BigDecimal cuotaMensual,
            BigDecimal totalAPagar,
            LocalDateTime fechaHora) {
    }

    private static class FakeSimulationRepository implements SimulationRepository {
        final List<SavedCall> calls = new ArrayList<>();
        private int next = 1;

        @Override
        public int save(BigDecimal monto, Integer plazo, BigDecimal tasaAnual, BigDecimal cuotaMensual,
                        BigDecimal totalAPagar, LocalDateTime fechaHora) {
            calls.add(new SavedCall(monto, plazo, tasaAnual, cuotaMensual, totalAPagar, fechaHora));
            return next++;
        }
    }

    private final FakeSimulationRepository repository = new FakeSimulationRepository();
    private final SimulateConsumerLoanService service = new SimulateConsumerLoanService(repository);

    private SimulateConsumerLoanResponse simulate(String monto, int plazo) {
        return service.execute(new SimulateConsumerLoanRequest(new BigDecimal(monto), plazo));
    }

    // ---- RULE-001

    @Test
    void rejects_an_amount_below_the_minimum() {
        assertThatThrownBy(() -> simulate("500.00", 12))
                .isInstanceOf(BusinessError.class)
                .hasMessage(AMOUNT_MESSAGE)
                .extracting(e -> ((BusinessError) e).code())
                .isEqualTo("AMOUNT_OUT_OF_RANGE");
    }

    @Test
    void accepts_the_lower_amount_limit() {
        SimulateConsumerLoanResponse response = simulate("1000.00", 12);

        assertThat(response).isNotNull();
        assertThat(repository.calls).hasSize(1);
    }

    @Test
    void accepts_the_upper_amount_limit() {
        SimulateConsumerLoanResponse response = simulate("50000.00", 12);

        assertThat(response).isNotNull();
        assertThat(repository.calls).hasSize(1);
    }

    // ---- RULE-002

    @Test
    void rejects_a_term_above_the_maximum() {
        assertThatThrownBy(() -> simulate("10000.00", 72))
                .isInstanceOf(BusinessError.class)
                .hasMessage(TERM_MESSAGE)
                .extracting(e -> ((BusinessError) e).code())
                .isEqualTo("TERM_OUT_OF_RANGE");
    }

    @Test
    void accepts_the_lower_term_limit() {
        SimulateConsumerLoanResponse response = simulate("10000.00", 6);

        assertThat(response).isNotNull();
        assertThat(repository.calls).hasSize(1);
    }

    @Test
    void accepts_the_upper_term_limit() {
        SimulateConsumerLoanResponse response = simulate("10000.00", 60);

        assertThat(response).isNotNull();
        assertThat(repository.calls).hasSize(1);
    }

